def choose_move(observation):
    x, y = observation['self_position']
    width, height = observation['grid_width'], observation['grid_height']

    def in_bounds(nx, ny):
        return 0 <= nx < width and 0 <= ny < height

    moves = [(0,0), (1,0), (-1,0), (0,1), (0,-1)]
    # Prefer moving towards the closest resource if available
    resources = observation.get('resources', [])
    def dist(a, b):
        return abs(a[0]-b[0]) + abs(a[1]-b[1])
    target = None
    if resources:
        target = min(resources, key=lambda r: dist((x,y), r))
    # Avoid obstacles
    obstacles = set(observation.get('obstacles', []))
    # Decide move
    best_move = (0,0)
    best_score = -1
    for dx, dy in moves:
        nx, ny = x + dx, y + dy
        if in_bounds(nx, ny) and (nx, ny) not in obstacles:
            score = 0
            if target:
                score -= dist((nx, ny), target)
            else:
                score += 1  # no target, prefer staying put
            if score > best_score:
                best_score = score
                best_move = (dx, dy)
    return list(best_move)
